import{_ as t,o as s,c as a,ag as o}from"./chunks/framework.DB9Ll7VW.js";const u=JSON.parse('{"title":"Blocks & page builders","description":"Use Sikshya with the WordPress block editor (Gutenberg), Elementor, Divi, Bricks, and Oxygen — through shortcodes, dynamic templates, and CPT-aware widgets.","frontmatter":{"title":"Blocks & page builders","description":"Use Sikshya with the WordPress block editor (Gutenberg), Elementor, Divi, Bricks, and Oxygen — through shortcodes, dynamic templates, and CPT-aware widgets."},"headers":[],"relativePath":"elementor-integration.md","filePath":"elementor-integration.md","lastUpdated":1778327862000}'),i={name:"elementor-integration.md"};function r(l,e,n,d,c,h){return s(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="blocks-page-builders" tabindex="-1">Blocks &amp; page builders <a class="header-anchor" href="#blocks-page-builders" aria-label="Permalink to &quot;Blocks &amp; page builders&quot;">​</a></h1><p>Sikshya is built to <strong>cooperate</strong> with WordPress page builders, not replace them. Course content lives as standard custom post types (<code>sik_course</code>, <code>sik_lesson</code>, <code>sik_quiz</code>), so any builder that knows about WordPress posts can render Sikshya content. Below is a per-builder cheat sheet.</p><h2 id="block-editor-gutenberg" tabindex="-1">Block editor (Gutenberg) <a class="header-anchor" href="#block-editor-gutenberg" aria-label="Permalink to &quot;Block editor (Gutenberg)&quot;">​</a></h2><p>Sikshya doesn&#39;t ship a dedicated Sikshya block yet — use the built-in <strong>Shortcode block</strong>:</p><ol class="step-list"><li>Add a new <strong>Shortcode</strong> block.</li><li>Paste any of the <a href="/shortcodes">Sikshya shortcodes</a>:</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[sikshya_courses per_page=&quot;6&quot; columns=&quot;3&quot;]</span></span>
<span class="line"><span>[sikshya_login]</span></span>
<span class="line"><span>[sikshya_registration redirect_to=&quot;/my-learning/&quot;]</span></span></code></pre></div><p>For full-site editing (FSE) themes, Sikshya respects your theme&#39;s color palette, typography, and width settings inside its templates.</p><h2 id="elementor" tabindex="-1">Elementor <a class="header-anchor" href="#elementor" aria-label="Permalink to &quot;Elementor&quot;">​</a></h2><p>Free Elementor works well with Sikshya:</p><ul><li><strong>Shortcode widget</strong> — drop in <code>[sikshya_courses ...]</code> for a course grid, or the auth shortcodes.</li><li><strong>Posts widget</strong> — set the <strong>Source</strong> to <strong>Posts</strong> and <strong>Post Type</strong> to <strong>Courses</strong>. You then style cards with Elementor&#39;s controls.</li><li><strong>Loop Grid</strong> — works with <code>sik_course</code> as the source post type.</li></ul><p>Pro Elementor users can build a full <strong>Single Course</strong> template via the Theme Builder, using the Posts widget for title, content, image, and a Shortcode widget for the <strong>Enroll</strong> CTA.</p><h2 id="divi" tabindex="-1">Divi <a class="header-anchor" href="#divi" aria-label="Permalink to &quot;Divi&quot;">​</a></h2><p>Divi is supported via:</p><ul><li><strong>Code Module</strong> for shortcodes.</li><li><strong>Theme Builder</strong> — assign a Divi template to <strong>Sikshya Courses</strong> custom post type.</li><li><strong>Blog module</strong> — set <strong>Post Type</strong> to <code>sik_course</code> for a Divi-styled grid.</li></ul><h2 id="beaver-builder-bricks-oxygen" tabindex="-1">Beaver Builder, Bricks, Oxygen <a class="header-anchor" href="#beaver-builder-bricks-oxygen" aria-label="Permalink to &quot;Beaver Builder, Bricks, Oxygen&quot;">​</a></h2><p>These builders all support custom post types out of the box:</p><ul><li>Use a <strong>Posts</strong> module / element with the post type set to <code>sik_course</code>.</li><li>Use a <strong>Shortcode</strong> module for the auth forms and the catalog grid.</li><li>Use <strong>Dynamic Data</strong> to bind to course meta (price, difficulty, instructor) for designer-controlled cards.</li></ul><h2 id="templating-override-the-universal-escape-hatch" tabindex="-1">Templating override (the universal escape hatch) <a class="header-anchor" href="#templating-override-the-universal-escape-hatch" aria-label="Permalink to &quot;Templating override (the universal escape hatch)&quot;">​</a></h2><p>Every Sikshya template can be overridden by your theme. Sikshya looks in <code>wp-content/themes/{your-theme}/sikshya/</code> first and falls back to the plugin defaults.</p><p>To customize a course card:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wp-content/themes/your-theme/sikshya/partials/courses</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wp-content/plugins/sikshya/templates/partials/courses/card.php</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">   wp-content/themes/your-theme/sikshya/partials/courses/card.php</span></span></code></pre></div><p>Then edit the copy in your theme. Plugin updates won&#39;t overwrite it.</p><h3 id="frequently-overridden-templates" tabindex="-1">Frequently overridden templates <a class="header-anchor" href="#frequently-overridden-templates" aria-label="Permalink to &quot;Frequently overridden templates&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Path (under <code>templates/</code>)</th><th>What it renders</th></tr></thead><tbody><tr><td><code>single-course.php</code></td><td>Single course page</td></tr><tr><td><code>archive-sik_course.php</code></td><td>Main <code>/courses/</code> archive</td></tr><tr><td><code>partials/courses/card.php</code></td><td>Course card (the most-styled file)</td></tr><tr><td><code>learn.php</code></td><td>Learn hub shell (lesson player)</td></tr><tr><td><code>checkout.php</code>, <code>cart.php</code>, <code>order.php</code></td><td>Commerce screens</td></tr><tr><td><code>account.php</code></td><td>Learner account shell</td></tr><tr><td><code>login.php</code></td><td>Virtual login page</td></tr></tbody></table><h2 id="css-theme-compatibility" tabindex="-1">CSS / theme compatibility <a class="header-anchor" href="#css-theme-compatibility" aria-label="Permalink to &quot;CSS / theme compatibility&quot;">​</a></h2><p>Sikshya targets broad theme compatibility but is designed against a <strong>default WordPress theme</strong>. If something looks off, briefly switch to <strong>Twenty Twenty-Five</strong> to isolate theme CSS. Common issues:</p><ul><li>Themes that force <code>box-shadow: none !important</code> on every card.</li><li>Themes that disable padding on <code>.entry-content</code>.</li><li>Themes that override <code>.button</code> styles too aggressively.</li></ul><p>Most are 5-line fixes in your child theme.</p><h2 id="caching-cdn-image-plugins" tabindex="-1">Caching, CDN, image plugins <a class="header-anchor" href="#caching-cdn-image-plugins" aria-label="Permalink to &quot;Caching, CDN, image plugins&quot;">​</a></h2><p>Catalog partials cache well at the page level. Caveats:</p><ul><li>Exclude <code>/cart/</code>, <code>/checkout/</code>, <code>/my-learning/</code>, <code>/order/</code>, and <code>/learn/</code> from full-page caching.</li><li>Bypass cache for logged-in users on course pages (so progress is accurate).</li><li>Lazy-loading images is fine — cards include explicit width/height for CLS.</li><li>WebP via image plugins (ShortPixel, EWWW) works without changes.</li></ul><h2 id="translation-plugins" tabindex="-1">Translation plugins <a class="header-anchor" href="#translation-plugins" aria-label="Permalink to &quot;Translation plugins&quot;">​</a></h2><p>Sikshya&#39;s text domain is <code>sikshya</code>.</p><ul><li><strong>Loco Translate</strong> — in-WordPress translation editing.</li><li><strong>WPML</strong> — multilingual catalogs (course content + UI strings). The Pro <strong>Multilingual</strong> add-on registers Sikshya strings with WPML String Translation.</li><li><strong>Polylang</strong> — register CPTs / taxonomies in Polylang settings; Polylang manages translations.</li><li><strong>TranslatePress / Weglot / GTranslate</strong> — site-wide translation overlays.</li></ul><div class="pro-callout"><div class="pro-callout__head"><span class="pro-callout__badge">PRO</span><span class="pro-callout__title">Multilingual (WPML / Weglot)</span></div><p class="pro-callout__desc">Bridge Sikshya&#39;s interface strings into WPML or Weglot translation stacks for fully multilingual catalogs.</p><a class="pro-callout__cta" href="https://mantrabrain.com/plugins/sikshya-lms/pricing/">Unlock multilingual →</a></div><h2 id="seo-plugins" tabindex="-1">SEO plugins <a class="header-anchor" href="#seo-plugins" aria-label="Permalink to &quot;SEO plugins&quot;">​</a></h2><p>Yoast SEO, Rank Math, and SEOPress all index Sikshya courses correctly. Sikshya&#39;s CPT and templates are SEO-friendly out of the box (clean URLs, proper title hierarchy, meta description hooks).</p><h2 id="multisite" tabindex="-1">Multisite <a class="header-anchor" href="#multisite" aria-label="Permalink to &quot;Multisite&quot;">​</a></h2><p>Sikshya is <code>Network: true</code>. Each subsite gets its own data. The Pro <strong>Multisite &amp; network license tools</strong> (Scale band) helps you manage licenses across subsites.</p><h2 id="what-s-next" tabindex="-1">What&#39;s next <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s next&quot;">​</a></h2><ul><li><a href="/docs/shortcodes">Shortcodes</a> — every shortcode attribute.</li><li><a href="/docs/woocommerce-integration">WooCommerce co-existence</a>.</li><li><a href="/docs/third-party-integrations">Pro add-ons</a>.</li></ul>`,41)])])}const g=t(i,[["render",r]]);export{u as __pageData,g as default};
